import"./hoisted.BQh-Wvb4.js";const e=document.getElementById("lead-form"),t=document.getElementById("form-status");e?.addEventListener("submit",async n=>{if(n.preventDefault(),!!t){t.style.display="block",t.textContent="Submitting...";try{const o=new FormData(e);(await fetch("/api/lead",{method:"POST",body:JSON.stringify(Object.fromEntries(o)),headers:{"Content-Type":"application/json"}})).ok?(t.textContent="Thank you. We will be in touch within one business day.",e.reset()):t.textContent="Something went wrong. Please try again or email hello@annai.sg."}catch{t.textContent="Something went wrong. Please try again or email hello@annai.sg."}}});
